  blocks: {
    "guide_paying_alw_link": "<a href=\"https://www.dhcs.ca.gov/services/long-term-care-alternatives-home-and-community-based-service-options/assisted-living-waiver/\" rel=\"noopener\" class=\"text-brand-green underline font-semibold\">Tìm hiểu về Assisted Living Waiver trên trang web của Medi-Cal</a>",
    "guide_paying_va_link": "<a href=\"https://www.va.gov/pension/aid-attendance-housebound/\" rel=\"noopener\" class=\"text-brand-green underline font-semibold\">Tìm hiểu về Aid and Attendance trên trang web của VA</a>",
    "guide_paying_hicap": "HICAP, Chương trình Tư vấn và Hỗ trợ Bảo hiểm Sức khỏe miễn phí của California (Health Insurance Counseling and Advocacy Program), có thể giải thích về Medicare, Medi-Cal và bảo hiểm chăm sóc dài hạn. Các tư vấn viên của chương trình không bán bảo hiểm. Hãy gọi số <a href=\"tel:+18004340222\" data-native-tel class=\"text-brand-green underline font-semibold whitespace-nowrap\">1-800-434-0222</a> để tìm văn phòng gần bạn.",
    "guide_memory_helpline": "Hiệp hội Alzheimer (Alzheimer's Association) có đường dây trợ giúp miễn phí 24 giờ dành cho người sống với chứng sa sút trí tuệ và gia đình họ: <a href=\"tel:+18002723900\" data-native-tel class=\"text-brand-green underline font-semibold whitespace-nowrap\">1-800-272-3900</a>.",
    "guide_choosing_assessment": "Chưa biết bắt đầu từ đâu? Bài <a data-view-link=\"tools\" href=\"#tools\" class=\"text-brand-green underline font-semibold\">Đánh giá mức chăm sóc</a> miễn phí của chúng tôi chỉ mất hai phút và giúp bạn có điểm khởi đầu.",
    "guide_choosing_type_small": "<strong class=\"text-brand-ink\">Nhà chăm sóc nhỏ (board and care):</strong> thường có từ sáu cư dân trở xuống, trong một ngôi nhà ở khu dân cư. Việc chăm sóc mang tính cá nhân, và nhân viên hiểu rõ từng cư dân.",
    "guide_choosing_type_large": "<strong class=\"text-brand-ink\">Cộng đồng hỗ trợ sinh hoạt (assisted living):</strong> các tòa nhà lớn hơn với nhiều cư dân, hoạt động và tiện nghi hơn.",
    "guide_choosing_type_memory": "<strong class=\"text-brand-ink\">Chăm sóc trí nhớ (memory care):</strong> nhà hoặc khu riêng cho người sống chung với chứng sa sút trí tuệ, có thêm biện pháp an toàn và nhân viên được đào tạo đặc biệt.",
    "guide_choosing_calculator": "Công cụ <a data-view-link=\"tools\" href=\"#tools\" class=\"text-brand-green underline font-semibold\">Ước tính chi phí</a> của chúng tôi cho biết mức chi phí hằng tháng thông thường ở khu vực của bạn.",
    "guide_choosing_search_link": "<a href=\"https://www.ccld.dss.ca.gov/carefacilitysearch/\" rel=\"noopener\" class=\"text-brand-green underline font-semibold\">Tra cứu nhà chăm sóc trên trang web Care Facility Search của tiểu bang</a>",
    "guide_choosing_ombudsman": "Chương trình Thanh tra viên Chăm sóc Dài hạn của California (Long-Term Care Ombudsman) giúp đỡ miễn phí những người sống trong các nhà chăm sóc. Nếu bạn lo lắng về việc chăm sóc hoặc sự an toàn của cha mẹ, hãy gọi đường dây khẩn cấp CRISISline 24 giờ theo số <a href=\"tel:+18002314024\" data-native-tel class=\"text-brand-green underline font-semibold whitespace-nowrap\">1-800-231-4024</a>. Mọi nhà chăm sóc có giấy phép đều phải niêm yết thông tin liên lạc của thanh tra viên tại địa phương.",
    "hero_title": "Thêm một chút rõ ràng.<br><span class=\"italic text-brand-green font-normal\">Thêm thật nhiều yêu thương.</span>",
    "va_subsidy_note": "<strong>Khả năng hỗ trợ tài chính (Mức VA 2025–2026):</strong> Cựu chiến binh độc thân đủ điều kiện có thể nhận tới <strong>$2,424/tháng</strong> (hoặc tới <strong>$2,874/tháng</strong> nếu có vợ/chồng phụ thuộc, và tới <strong>$1,558/tháng</strong> cho vợ/chồng còn sống) thông qua trợ cấp VA Aid &amp; Attendance để bù đắp chi phí RCFE hàng tháng.",
    "urgent_notice_p": "Với thời gian chuyển tiếp gấp trong 1–7 ngày, giường trống ngay và giấy đánh giá y tế (LIC 602A) cần được xử lý khẩn. Hãy gọi trực tiếp cho đội tiếp nhận ưu tiên theo số <a href=\"tel:+18182175755\" data-call class=\"underline font-bold text-brand-ink dark:text-amber-300\">(818) 217-5755</a> để hỏi chỗ trống trong ngày.",
    "modal_urgent_p": "Với khung thời gian khẩn 1–7 ngày, hãy gọi đường dây tiếp nhận <a href=\"tel:+18182175755\" data-call class=\"underline font-bold text-brand-ink dark:text-amber-300\">(818) 217-5755</a> để hỏi chỗ trống khẩn cấp và đặt lịch tham quan ưu tiên.",
    "faq1_body": "<strong>RCFE (Cơ sở Chăm sóc Nội trú cho Người cao tuổi)</strong>—thường được gọi là cộng đồng sinh hoạt có hỗ trợ hoặc nhà chăm sóc gia đình 6 giường (Board &amp; Care)—được thiết kế cho người cao tuổi cần hỗ trợ sinh hoạt hàng ngày (ăn uống, tắm rửa, mặc đồ, quản lý thuốc) trong môi trường ấm áp như ở nhà. <br><br><strong>Cơ sở Điều dưỡng Chuyên môn (SNF)</strong> là cơ sở y tế giống bệnh viện, cung cấp chăm sóc y tá có giấy phép 24/24, truyền dịch tĩnh mạch và chăm sóc vết thương cấp tính. Nhiều gia đình chọn RCFE có giấy miễn trừ chăm sóc cuối đời (hospice waiver) để người thân được an hưởng tuổi già tại một mái ấm quen thuộc.",
    "faq2_body": "<strong>Medicare thông thường không chi trả</strong> tiền phòng và ăn ở tại RCFE (chỉ chi trả khám bác sĩ, nằm viện và phục hồi chức năng ngắn hạn). <br><br>Tuy nhiên, tại California, chương trình <strong>Miễn trừ Sinh hoạt Hỗ trợ Medi-Cal (ALW)</strong> có thể chi trả phần chi phí chăm sóc tại các cơ sở được chứng nhận cho người thu nhập thấp đủ điều kiện. Ngoài ra, trợ cấp Veterans Aid &amp; Attendance và Bảo hiểm Chăm sóc Dài hạn thường giúp bù đắp chi phí. Chúng tôi hỗ trợ gia đình đánh giá các lựa chọn này.",
    "faq3_body": "Thời gian tiêu chuẩn thường từ <strong>4 đến 8 tháng</strong>, tùy thuộc vào tốc độ kiểm tra phòng cháy chữa cháy STD 850 của sở cứu hỏa địa phương và lượng hồ sơ tồn đọng tại văn phòng CDSS khu vực. Hồ sơ LIC 200 chính xác ngay từ đầu cùng Kế hoạch Vận hành đạt chuẩn sẽ rút ngắn nhiều tháng chờ đợi.",
    "faq5_family": "Dịch vụ đánh giá nhu cầu, đưa đi tham quan cơ sở và tư vấn tìm nơi ở của chúng tôi là <strong>hoàn toàn miễn phí cho gia đình</strong>. Tương tự như người môi giới bảo hiểm hoặc đại diện người thuê nhà, chỉ khi người thân của bạn chuyển vào an toàn thì cơ sở được cấp phép mới trả cho chúng tôi phí giới thiệu tiêu chuẩn từ ngân sách vận hành của họ. Tiền thuê hàng tháng của bạn không bao giờ bị đội giá và bạn sẽ không bao giờ nhận hóa đơn từ chúng tôi.",
    "faq5_operator": "Chủ sở hữu nhà chăm sóc nội trú tương lai, quản trị viên và nhà đầu tư trả <strong>phí tư vấn chuyên nghiệp minh bạch, trọn gói</strong> cho dịch vụ xin giấy phép Title 22 California của chúng tôi (soạn bộ hồ sơ LIC 200, viết Kế hoạch Vận hành, hướng dẫn giấy phép PCCC và chuẩn bị thanh tra trước cấp phép với LPA).",
    "privacy4_p": "Bạn có quyền xem, chỉnh sửa hoặc yêu cầu xóa bất kỳ thông tin liên hệ nào chúng tôi lưu giữ. Chỉ cần gửi email đến <a href=\"mailto:loveRCFE@gmail.com\" class=\"text-brand-green underline font-semibold\">loveRCFE@gmail.com</a> với tiêu đề \"Data Removal Request.\""
  }
